pub struct AccountedFailure { pub error: CoreError, pub work: WorkCounters }

fn require_fused(report: FusedPhiActionReport, work: &WorkCounters) -> Result<FusedPhiActionReport, AccountedFailure> {
    if report.converged { Ok(report) } else {
        Err(AccountedFailure { error: CoreError::LinearSolve(format!(
            "fused phi action failed after {} substeps at dimension {} (estimate {})",
            report.substeps, report.maximum_krylov_dimension, report.error_estimate)),
            work: work.clone() })
    }
}
