fn stiff_coupled_problem(lambda: f64) -> OdeProblem {
    // y1' = lambda*(y1 - cos t) - sin t + y2^2 ; y2' = -y2 + y1*y2 ; J and N do not commute
    OdeProblem::new("stiff-coupled", 2,
        Arc::new(move |t, y: &[f64], out: &mut [f64]| {
            out[0] = lambda * (y[0] - t.cos()) - t.sin() + y[1] * y[1];
            out[1] = -y[1] + y[0] * y[1];
            Ok(())
        }), None, None,
        Some(Arc::new(move |_, y: &[f64], v: &[f64], out: &mut [f64]| {
            out[0] = lambda * v[0] + 2.0 * y[1] * v[1];
            out[1] = y[1] * v[0] + (y[0] - 1.0) * v[1];
            Ok(())
        })), None, true, None, None).expect("stiff coupled problem")
}
#[test]
fn pexprb54s4_stiff_order_is_measured_on_nonscalar_problem() {
    let stiff = observed_global_order_on(&stiff_coupled_problem(-1.0e4), "pexprb54s4", &[1e-2, 5e-3, 2.5e-3, 1.25e-3]);
    let nonstiff = observed_local_order_on(&stiff_coupled_problem(-1.0), "pexprb54s4", &[4e-2, 2e-2, 1e-2, 5e-3]);
    assert!(nonstiff >= 4.7, "nonstiff local order {nonstiff}");
    assert!(stiff >= 3.8, "stiff global order {stiff} (D4 run: 4.08-4.15)");
}
